INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 7, 'theory', 'Quiz: Search and Files');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 7, 0, 'Why is a substring query a poor fit for searching a big table?', '["Databases do not support it", "It scans every row, does not rank, and ignores language", "It is too cheap", "It requires shards"]', 1, 'A substring without an index means a full scan; for search we build an inverted index.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 7, 1, 'What does an inverted index store?', '["For each document, its author", "For each word, the list of documents where it occurs", "A copy of the whole database", "Only popular queries"]', 1, 'A query by words turns into an intersection of document lists.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 7, 2, 'What determines the number of replicas of a search cluster, and what determines the number of shards?', '["Replicas set the volume, shards set the load", "Shards set the index volume, replicas set throughput and fault tolerance", "Both are about cost", "Shards are about language, replicas about region"]', 1, 'There are as many shards as needed to keep a shard under a few tens of gigabytes; replicas are added for queries and reliability.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 7, 3, 'What is the right way to upload big files?', '["Whole, through the application server", "Straight to object storage via a temporary signed link, in parts", "Through the database", "By email"]', 1, 'This way the application does not spend connections and memory on moving bytes; resuming works part by part.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 7, 4, 'Why is a search index not considered the source of truth?', '["It is too small", "It is a derived copy: if lost, it is rebuilt from the main database", "It does not store text", "It is stored in the browser"]', 1, 'The source of truth is the main database; the index is updated asynchronously and may lag.');
